'use strict';

// MODULES //

var cos = require( '@stdlib/math/base/special/cos' );


// MAIN //

/**
* Computes the versed cosine.
*
* @param {number} x - input value (in radians)
* @returns {number} versed cosine
*
* @example
* var v = vercos( 0.0 );
* // returns 2.0
*
* @example
* var v = vercos( 3.141592653589793/2.0 );
* // returns 1.0
*
* @example
* var v = vercos( -3.141592653589793/6.0 );
* // returns ~1.8660
*
* @example
* var v = vercos( NaN );
* // returns NaN
*/
function vercos( x ) {
	var c;

	// Use the half-angle identity `1 + cos(x) = 2*cos(x/2)^2`, as evaluating `1 + cos(x)` directly loses all significant digits when `cos(x)` is close to negative one (e.g., for `x` near odd multiples of π):
	c = cos( x / 2.0 );
	return 2.0 * c * c;
}


// EXPORTS //

module.exports = vercos;
